// src: J26 = NEC exam Jan 2026 (recalled, necmcq), R = recalled by candidates (your notes),
// PQ = BCT past-question collection, P = practice question written for this site
const Q = [
// ---------- Chapter 1 ----------
{s:"1.1",src:"J26",q:"Which of the following is a passive circuit element?",o:["Voltage source","Current source","Resistor","Transistor amplifier"],a:2,e:"Passive elements (R, L, C) only dissipate or store energy. Sources and amplifiers deliver energy, so they are active. (The original recalled options listed 'Transformer', which is also passive, so that option was replaced here.)"},
{s:"1.1",src:"R",q:"Resistors connected in parallel act as a ___ divider.",o:["Voltage","Current","Power","Frequency"],a:1,e:"Parallel branches share the same voltage and split the total current, so a parallel network is a current divider. Series resistors divide voltage."},
{s:"1.1",src:"R",q:"Ohm (Ω) is the SI unit of all of the following EXCEPT:",o:["Inductive reactance","Capacitive reactance","Resistance","Capacitance"],a:3,e:"Capacitance is measured in farads. Resistance, reactance and impedance are all in ohms."},
{s:"1.1",src:"R",q:"A balanced star load has impedance Z1 per phase and an equivalent delta has Z2 per phase. The relation is:",o:["Z2 = Z1","Z2 = 2Z1","Z2 = 3Z1","Z2 = Z1/3"],a:2,e:"For balanced loads Z_Δ = 3·Z_Y (and Z_Y = Z_Δ/3)."},
{s:"1.1",src:"P",q:"Kirchhoff's current law is based on the conservation of:",o:["Energy","Charge","Momentum","Power"],a:1,e:"KCL: charge cannot accumulate at a node, so currents in = currents out. KVL is based on conservation of energy."},
{s:"1.2",src:"J26",q:"When applying the superposition theorem, what should be done with a dependent source?",o:["Remove it completely","Replace it with its internal resistance","Keep it active","Replace it with an open circuit"],a:2,e:"Only independent sources are switched off (voltage sources shorted, current sources opened). Dependent sources stay in the circuit because they depend on circuit variables."},
{s:"1.2",src:"R",q:"The superposition theorem can be applied to:",o:["Linear circuits","Non-linear circuits","Circuits with diodes only","Any circuit"],a:0,e:"Superposition needs linearity (additivity and homogeneity). It does not apply to non-linear circuits or directly to power."},
{s:"1.2",src:"P",q:"Maximum power is transferred to a load when:",o:["R_L = 0","R_L = R_th","R_L = 2R_th","R_L is infinite"],a:1,e:"Maximum power transfer occurs at R_L = R_th, giving P_max = V_th²/4R_th at 50% efficiency."},
{s:"1.2",src:"P",q:"At resonance in a series RLC circuit:",o:["Impedance is maximum","Current is minimum","Impedance is minimum and equals R","Power factor is zero"],a:2,e:"X_L = X_C cancel, so Z = R (minimum), current is maximum and power factor is unity."},
{s:"1.3",src:"J26",q:"In three-phase systems, which configuration has a neutral point that is grounded?",o:["Star","Delta","Bridge","Both star and delta equally"],a:0,e:"Star (Y) has a common neutral point that can be earthed. Delta forms a closed loop with no neutral."},
{s:"1.3",src:"J26",q:"Two sinusoids of the same frequency but different amplitude and phase are subtracted. The result is:",o:["A sinusoid of the same frequency","A cosine wave of double frequency","A square wave","A constant"],a:0,e:"Phasor subtraction at one frequency gives another phasor at that frequency, with new amplitude and phase."},
{s:"1.3",src:"R",q:"Find the time period of y(t) = 5 sin(4t + π/6).",o:["π/4 s","π/2 s","2π s","4 s"],a:1,e:"ω = 4 rad/s, so T = 2π/ω = 2π/4 = π/2 s. The phase does not affect the period."},
{s:"1.3",src:"P",q:"The rms value of a sine wave with peak value V_m is:",o:["V_m/2","V_m/√2","2V_m/π","√2·V_m"],a:1,e:"V_rms = V_m/√2 ≈ 0.707V_m. The half-cycle average is 2V_m/π ≈ 0.637V_m."},
{s:"1.3",src:"P",q:"In a balanced star-connected system, line voltage equals:",o:["Phase voltage","√3 × phase voltage","3 × phase voltage","Phase voltage / √3"],a:1,e:"Star: V_L = √3·V_ph and I_L = I_ph. Delta: I_L = √3·I_ph and V_L = V_ph."},
{s:"1.4",src:"J26",q:"The main advantage of CMOS technology over bipolar technology is:",o:["Higher speed","Better analog performance","Lower power consumption","Larger circuit size"],a:2,e:"In CMOS one transistor of each pair is off in steady state, so it draws power mainly while switching."},
{s:"1.4",src:"R",q:"Which is the most stable BJT biasing technique?",o:["Fixed bias","Collector-to-base bias","Voltage divider bias","Emitter bias without bypass"],a:2,e:"Voltage divider bias makes the Q-point almost independent of β, so it is the most stable and the most widely used."},
{s:"1.4",src:"R",q:"The voltage gain of a common collector (emitter follower) amplifier is approximately:",o:["0","1","100","Very high"],a:1,e:"An emitter follower has voltage gain just below 1, high input impedance and low output impedance. It is used as a buffer."},
{s:"1.4",src:"P",q:"A MOSFET has very high input impedance because:",o:["Its channel is heavily doped","The gate is insulated by an oxide layer","It uses both electrons and holes","Its drain is grounded"],a:1,e:"The gate is separated from the channel by SiO₂, so almost no gate current flows."},
{s:"1.5",src:"R",q:"Oscillators work on which type of feedback?",o:["Positive","Negative","No feedback","Both alternately"],a:0,e:"Oscillators use positive (regenerative) feedback. Negative feedback is used to stabilize amplifiers."},
{s:"1.5",src:"R",q:"A multivibrator is a type of:",o:["Sinusoidal oscillator","Non-sinusoidal (relaxation) oscillator","Tuned amplifier","Rectifier"],a:1,e:"Multivibrators produce square/rectangular waves, so they are non-sinusoidal (relaxation) oscillators."},
{s:"1.5",src:"P",q:"The Barkhausen criterion for sustained oscillation is:",o:["|Aβ| < 1, phase 180°","|Aβ| = 1, loop phase 0° or 360°","|Aβ| > 10","Aβ = −1, phase 90°"],a:1,e:"Loop gain magnitude must be 1 and total phase shift around the loop 0° (360°)."},
{s:"1.5",src:"P",q:"In an RC phase-shift oscillator, the RC network provides a phase shift of:",o:["90°","120°","180°","360°"],a:2,e:"Three RC sections give 180°; the inverting amplifier gives the other 180°, totalling 360°."},
{s:"1.5",src:"P",q:"Crystal oscillators are preferred mainly for their:",o:["High output power","Frequency stability","Low cost","Wide tuning range"],a:1,e:"The quartz crystal has a very high Q, giving excellent frequency stability."},
{s:"1.6",src:"J26",q:"The maximum efficiency of a series-fed (resistive load) Class A amplifier is:",o:["25%","50%","78.5%","90%"],a:0,e:"Series-fed Class A: 25%. Transformer-coupled Class A: 50%. Class B push-pull: 78.5% (π/4). The recalled explanation that gave π/4 for Class A was wrong; π/4 belongs to Class B."},
{s:"1.6",src:"R",q:"A Class B amplifier transistor is biased at:",o:["Saturation","Cut-off","Centre of the load line","Active region"],a:1,e:"Class B is biased at cut-off, so each transistor conducts for 180°."},
{s:"1.6",src:"R",q:"A tuned amplifier uses which type of filter?",o:["Low pass","High pass","Band pass","All pass"],a:2,e:"A tuned (LC) amplifier amplifies a narrow band around its resonant frequency, so it acts as a band-pass filter."},
{s:"1.6",src:"P",q:"Crossover distortion occurs in which amplifier class, and is removed by which?",o:["Class A; Class B","Class B; Class AB","Class C; Class A","Class AB; Class B"],a:1,e:"Class B transistors need ~0.7 V to turn on, causing crossover distortion. Class AB adds a small bias to remove it."},
{s:"1.6",src:"P",q:"An ideal op-amp has:",o:["Zero input impedance","Infinite output impedance","Infinite input impedance and zero output impedance","Unity open-loop gain"],a:2,e:"Ideal op-amp: infinite gain, infinite input impedance, zero output impedance, infinite bandwidth."},
// ---------- Chapter 2 ----------
{s:"2.1",src:"P",q:"Which gates are called universal gates?",o:["AND and OR","NAND and NOR","XOR and XNOR","NOT and AND"],a:1,e:"Any Boolean function can be built from only NAND gates or only NOR gates."},
{s:"2.1",src:"P",q:"(10110110)₂ in hexadecimal is:",o:["B6","6B","D6","A6"],a:0,e:"Group in 4s: 1011 = B, 0110 = 6 → B6H."},
{s:"2.1",src:"P",q:"By De Morgan's theorem, (A·B)' equals:",o:["A'·B'","A' + B'","A + B","(A + B)'"],a:1,e:"(AB)' = A' + B' and (A + B)' = A'B'."},
{s:"2.1",src:"R",q:"An expression written as a conjunction (AND) of disjunctions (ORs) is in:",o:["Sum of Products / DNF","Product of Sums / CNF","Backus–Naur form","Canonical SOP"],a:1,e:"AND of OR-terms = Product of Sums, also called Conjunctive Normal Form. OR of AND-terms is SOP/DNF."},
{s:"2.1",src:"P",q:"In a 4-variable K-map, a group of 8 adjacent 1s eliminates how many variables?",o:["1","2","3","4"],a:2,e:"A group of 2ᵏ cells removes k variables. 8 = 2³, so 3 variables drop out, leaving one literal."},
{s:"2.2",src:"J26",q:"How many half adders and full adders are needed for a 4-bit ripple-carry adder?",o:["2 half, 2 full","1 half, 3 full","0 half, 2 full","4 half, 0 full"],a:1,e:"The LSB has no carry-in, so it uses a half adder. The other three bits use full adders."},
{s:"2.2",src:"R",q:"To correct an invalid BCD sum (greater than 9), we add:",o:["0011","0110","1001","1111"],a:1,e:"Adding 6 (0110) skips the six unused codes 1010–1111 and produces the correct BCD digit with carry."},
{s:"2.2",src:"R",q:"Which of the following is NOT an encoder?",o:["8-to-3","4-to-2","16-to-4","5-to-32"],a:3,e:"An encoder has 2ⁿ inputs and n outputs. 5-to-32 has more outputs than inputs, which is a decoder."},
{s:"2.2",src:"P",q:"An 8-to-1 multiplexer needs how many select lines?",o:["2","3","4","8"],a:1,e:"2ⁿ inputs need n select lines; 8 = 2³."},
{s:"2.2",src:"P",q:"The 2's complement of 0101 is:",o:["1010","1011","0110","1101"],a:1,e:"Invert → 1010, add 1 → 1011 (which represents −5 in 4 bits)."},
{s:"2.3",src:"R",q:"The maximum count of a 4-bit ripple counter is:",o:["4","8","15","16"],a:2,e:"A 4-bit counter is mod-16 and counts 0 to 15. Maximum count = 2ⁿ − 1."},
{s:"2.3",src:"R",q:"Which of the following is NOT a type of shift register?",o:["SIPI","SISO","PISO","SIPO"],a:0,e:"The four types are SISO, SIPO, PISO and PIPO. SIPI does not exist."},
{s:"2.3",src:"P",q:"The race-around condition in a JK flip-flop is avoided by using:",o:["SR flip-flop","Master–slave JK flip-flop","D latch","Asynchronous reset"],a:1,e:"Race-around happens when J = K = 1 and the clock pulse is longer than the propagation delay. Master–slave (or edge triggering) fixes it."},
{s:"2.3",src:"P",q:"In a synchronous counter:",o:["Each flip-flop is clocked by the previous one","All flip-flops receive the same clock","Only the first flip-flop is clocked","No clock is used"],a:1,e:"All flip-flops share the clock, so there is no ripple delay. Asynchronous (ripple) counters clock each stage from the previous output."},
{s:"2.4",src:"J26",q:"What addressing mode does the 8085 instruction MOV A, M use?",o:["Register","Register indirect","Direct","Immediate"],a:1,e:"M is the memory location whose address is in the HL pair, so the operand is addressed indirectly through a register pair."},
{s:"2.4",src:"R",q:"The 8086 microprocessor can operate in which modes?",o:["Minimum and maximum","Internal and external","Real and virtual only","Single and dual"],a:0,e:"MN/MX' pin selects minimum mode (single processor) or maximum mode (with 8288 bus controller / coprocessors)."},
{s:"2.4",src:"P",q:"The 8085 has a 16-bit address bus. How much memory can it address?",o:["16 KB","32 KB","64 KB","1 MB"],a:2,e:"2¹⁶ = 65,536 bytes = 64 KB. The 8086 has 20 address lines → 1 MB."},
{s:"2.4",src:"R",q:"What does the ALE signal in the 8085 do?",o:["Enables the ALU","Latches the lower-order address from the multiplexed AD0–AD7 bus","Acknowledges interrupts","Resets the processor"],a:1,e:"Address Latch Enable goes high in T1 so an external latch can separate A0–A7 from the multiplexed address/data bus."},
{s:"2.4",src:"R",q:"Minimum number of bits needed to represent the memory address 2000H:",o:["12","13","14","16"],a:2,e:"2000H = 0010 0000 0000 0000₂. The highest 1 is bit 13, so 14 bits are needed."},
{s:"2.5",src:"R",q:"A microprocessor can directly execute a program only when it is stored in:",o:["Secondary memory","Main memory","Program counter","Hard disk"],a:1,e:"The CPU fetches instructions from main memory (RAM/ROM). Programs on secondary storage must be loaded first."},
{s:"2.5",src:"R",q:"A DMA transfer is requested (initiated) by:",o:["The processor","The I/O device","Memory","The running process"],a:1,e:"The I/O device asserts a DMA request; the DMA controller sends HOLD and the CPU responds with HLDA, giving up the bus."},
{s:"2.5",src:"R",q:"RS-232 is a standard for:",o:["Parallel communication","Serial communication","Wireless communication","Memory interfacing"],a:1,e:"RS-232 defines the electrical/physical interface for serial communication, typically driven by a UART/USART."},
{s:"2.5",src:"P",q:"The 8255 PPI provides how many I/O ports?",o:["Two 8-bit","Three 8-bit","Four 4-bit","One 16-bit"],a:1,e:"Ports A, B and C (C splits into two 4-bit halves) give 24 programmable I/O lines."},
{s:"2.5",src:"P",q:"In asynchronous serial transmission, each character is framed by:",o:["A clock signal","Start and stop bits","Sync characters","Parity only"],a:1,e:"Asynchronous transmission has no shared clock, so each character carries a start bit and one or more stop bits."},
{s:"2.6",src:"J26",q:"INT 3 is used for:",o:["Divide-by-zero","Debugger breakpoint","System call","Hardware interrupt"],a:1,e:"INT 3 (one-byte opcode CCH) is the breakpoint interrupt used by debuggers."},
{s:"2.6",src:"R",q:"Which is the non-maskable interrupt of the 8085?",o:["RST 7.5","RST 6.5","RST 5.5","TRAP"],a:3,e:"TRAP cannot be masked and has the highest priority."},
{s:"2.6",src:"R",q:"TRAP in the 8085 is:",o:["Positive-edge triggered only","Level triggered only","Both edge and level triggered","Negative-edge triggered"],a:2,e:"TRAP is both edge- and level-sensitive, which prevents false triggering. RST 7.5 is edge triggered; RST 6.5 and 5.5 are level triggered."},
{s:"2.6",src:"R",q:"RST 0 to RST 7 instructions in the 8085 are:",o:["Hardware interrupts","Software interrupts","Non-maskable interrupts","Vectored hardware interrupts"],a:1,e:"RST 0–7 are one-byte software interrupt instructions that jump to 8 × n."},
{s:"2.6",src:"R",q:"An interrupt that can be ignored (disabled) by the processor is called:",o:["Non-maskable","Maskable","Vectored","Software"],a:1,e:"Maskable interrupts can be disabled with DI or masks; non-maskable (e.g. TRAP) cannot."},
// ---------- Chapter 3 ----------
{s:"3.1",src:"J26",q:"Converting high-level code to machine/assembly code in one go before execution is called:",o:["Interpretation","Compilation","Linking","Loading"],a:1,e:"A compiler translates the whole program; an interpreter executes line by line; the linker combines object files; the loader places them in memory."},
{s:"3.1",src:"J26",q:"Which standard C function reads a single character from the keyboard?",o:["scanf()","getchar()","puts()","gets()"],a:1,e:"getchar() is the standard (stdio.h) single-character input function. getch() from conio.h also reads one character without Enter, but it is non-standard. The recalled key said getch(); if both appear and the question says 'without pressing Enter', choose getch()."},
{s:"3.1",src:"R",q:"Which of these cannot be used as a variable name in C?",o:["cat","_total","while","sum1"],a:2,e:"while is a keyword. Identifiers may contain letters, digits and underscores, and must not start with a digit."},
{s:"3.1",src:"P",q:"What does printf(\"%d\", 7/2); print in C?",o:["3.5","3","4","Compile error"],a:1,e:"Both operands are int, so integer division truncates: 7/2 = 3."},
{s:"3.1",src:"P",q:"int i = 5; printf(\"%d\", i++ + 1); prints:",o:["5","6","7","Undefined"],a:1,e:"Post-increment uses the old value 5, so 5 + 1 = 6 is printed; i becomes 6 afterwards."},
{s:"3.2",src:"R",q:"What value is EOF defined as in stdio.h?",o:["0","1","-1","'\\0'"],a:2,e:"EOF is a negative integer constant, −1 in practically all implementations."},
{s:"3.2",src:"P",q:"The size of a union is:",o:["Sum of all member sizes","Size of the largest member (plus padding)","Size of the first member","Always 4 bytes"],a:1,e:"Union members share the same memory, so it is as large as its largest member. A structure is at least the sum of its members."},
{s:"3.2",src:"P",q:"If int *p points to address 1000 and int is 4 bytes, p + 1 points to:",o:["1001","1002","1004","1008"],a:2,e:"Pointer arithmetic scales by the size of the pointed-to type: 1000 + 1×4 = 1004."},
{s:"3.2",src:"R",q:"How is a structure passed to a function by pointer in C?",o:["void f(struct st p) called as f(s)","void f(struct st *p) called as f(&s)","void f(struct st &p) called as f(s)","void f(&p) called as f(*s)"],a:1,e:"The parameter is a pointer to the structure and the caller passes the address with &. Members are then accessed with p->member. References (&p) exist only in C++."},
{s:"3.2",src:"P",q:"Which C function moves the file pointer to a specific position (random access)?",o:["fgets()","fseek()","fputc()","fclose()"],a:1,e:"fseek(fp, offset, origin) with SEEK_SET, SEEK_CUR or SEEK_END. ftell() reports the position and rewind() goes to the start."},
{s:"3.3",src:"J26",q:"Which access specifier makes members accessible within the class and its derived classes only?",o:["Public","Private","Protected","Internal"],a:2,e:"Protected members are visible to the class and its derived classes but not to outside code."},
{s:"3.3",src:"J26",q:"Bundling data and methods in a class and hiding them from outside interference is:",o:["Polymorphism","Inheritance","Encapsulation","Abstraction"],a:2,e:"Encapsulation = wrapping data and functions together with controlled access (data hiding)."},
{s:"3.3",src:"J26",q:"Which statement about static member functions in C++ is true?",o:["They can be virtual","They have no this pointer","They can access non-static members directly","They can never be overloaded"],a:1,e:"Static member functions belong to the class, not an object, so they have no this pointer, cannot be virtual and cannot touch non-static members directly. They CAN be overloaded with each other; the recalled key 'cannot be overloaded' is wrong for standard C++."},
{s:"3.3",src:"R",q:"Default member access in C++:",o:["struct private, class public","struct public, class private","Both public","Both private"],a:1,e:"Members of a struct are public by default; members of a class are private by default."},
{s:"3.3",src:"P",q:"An inline function:",o:["Is always placed in a separate file","Asks the compiler to substitute the function body at the call site","Cannot take arguments","Must be virtual"],a:1,e:"inline is a request to expand the body at each call, removing call overhead for small functions."},
{s:"3.3",src:"P",q:"A friend function of a class:",o:["Is a member function of that class","Can access the class's private members but is not a member","Is inherited by derived classes","Must be static"],a:1,e:"A friend is declared inside the class with the friend keyword but is not a member. Friendship is not inherited."},
{s:"3.4",src:"J26",q:"When a derived class object is created, which constructor runs first?",o:["Derived only","Base, then derived","Derived, then base","Both simultaneously"],a:1,e:"Base constructors run first, then the derived constructor. Destructors run in reverse order."},
{s:"3.4",src:"J26",q:"The main advantage of hybrid inheritance is:",o:["Code reusability","Reduced memory","Faster compilation","Simpler syntax"],a:0,e:"Combining inheritance types lets a class reuse code from several sources. Watch for the diamond problem."},
{s:"3.4",src:"R",q:"class Derived : public Base1, public Base2 { ... }; Each constructor prints its name. Creating a Derived object prints:",o:["Base1 Base2 Derived","Base2 Base1 Derived","Derived Base1 Base2","Derived Base2 Base1"],a:0,e:"Base constructors run in the order the bases are listed in the class declaration, then the derived constructor."},
{s:"3.4",src:"P",q:"Which operator cannot be overloaded in C++?",o:["+","[]","::","()"],a:2,e:"Not overloadable: :: (scope), . (member), .* , ?: and sizeof."},
{s:"3.4",src:"P",q:"Correct member-function syntax for overloading unary minus in class T:",o:["T operator-(T a, T b);","T operator-();","void -operator();","T operator(-)();"],a:1,e:"A unary operator as a member takes no arguments; it acts on *this. As a friend it takes one argument."},
{s:"3.4",src:"P",q:"The ambiguity of multipath (diamond) inheritance is resolved using:",o:["Friend classes","Virtual base classes","Templates","Static members"],a:1,e:"Declaring the common base as virtual ensures only one copy of it in the final derived object."},
{s:"3.5",src:"J26",q:"Which flag positions a C++ file pointer at the start of the file?",o:["ios::first","ios::beg","ios::start","ios::begin"],a:1,e:"Seek directions are ios::beg, ios::cur and ios::end, e.g. file.seekg(0, ios::beg)."},
{s:"3.5",src:"J26",q:"Which header is needed to use ifstream?",o:["<iostream>","<fstream>","<stdio.h>","<iomanip>"],a:1,e:"<fstream> defines ifstream, ofstream and fstream. <iomanip> has manipulators like setw."},
{s:"3.5",src:"PQ",q:"class A { public: virtual void display(){ cout<<\"A\"; } }; class B : public A { public: void display() override { cout<<\"B\"; } }; A* p = new B(); p->display(); prints:",o:["A","B","AB","Nothing"],a:1,e:"display is virtual, so the call is resolved at run time (dynamic binding) using the actual object type, B."},
{s:"3.5",src:"P",q:"A class containing at least one pure virtual function is:",o:["A friend class","An abstract class","A template class","A static class"],a:1,e:"virtual void f() = 0; makes the class abstract: it cannot be instantiated and derived classes must override f."},
{s:"3.5",src:"P",q:"Dynamic binding means:",o:["Linking libraries at compile time","Deciding which function to call at run time","Allocating memory with new","Binding variables to registers"],a:1,e:"Also called late binding; achieved with virtual functions through base-class pointers or references."},
{s:"3.6",src:"J26",q:"In C++, an exception is:",o:["A type of inheritance","A run-time anomaly that is handled with try, throw and catch","A compile-time syntax error","A class template"],a:1,e:"Exceptions are abnormal conditions at run time. The recalled answer 'a special function' is not accurate; pick the option describing a run-time error/abnormal condition."},
{s:"3.6",src:"J26",q:"In the STL, containers primarily hold:",o:["Functions and algorithms","Data elements and their organization","Only iterators","Memory addresses"],a:1,e:"Containers (vector, list, map, ...) store data; algorithms operate on them through iterators."},
{s:"3.6",src:"P",q:"Which catch block catches every exception?",o:["catch(all)","catch(...)","catch(*)","catch(exception)"],a:1,e:"catch(...) is the catch-all handler and should be placed last."},
{s:"3.6",src:"P",q:"A function template is declared with:",o:["template <class T>","generic <T>","typedef T","virtual template"],a:0,e:"template <class T> or template <typename T> before the function definition."},
{s:"3.6",src:"PQ",q:"try { throw 20; } catch (int e) { cout << \"Exception caught: \" << e; } prints:",o:["Exception caught: 20","Nothing","Compile error","Runtime abort"],a:0,e:"An int is thrown and caught by the matching catch(int) handler."},
// ---------- Chapter 4 ----------
{s:"4.1",src:"J26",q:"Which is a characteristic of CISC architecture?",o:["Fixed-length simple instructions","Only load/store instructions access memory","A large set of complex, variable-length instructions","All instructions execute in one cycle"],a:2,e:"CISC has many complex instructions of variable length and many addressing modes. The other three options describe RISC. (The recalled option 'small number of complex instructions' was wrong.)"},
{s:"4.1",src:"P",q:"Which is a feature of RISC processors?",o:["Microprogrammed complex instructions","Variable instruction length","Load/store architecture with fixed-length instructions","Few registers"],a:2,e:"RISC: simple fixed-length instructions, many registers, hardwired control, load/store, pipeline-friendly."},
{s:"4.1",src:"P",q:"An instruction needs the result of the previous instruction that has not finished. This pipeline hazard is a:",o:["Structural hazard","Data hazard","Control hazard","Memory hazard"],a:1,e:"Data hazards come from data dependencies; control hazards from branches; structural hazards from resource conflicts."},
{s:"4.1",src:"P",q:"In a microprogrammed control unit, control signals are stored in:",o:["Cache","Control memory","Registers only","Hard disk"],a:1,e:"Microinstructions live in control memory (control store), addressed by a sequencer."},
{s:"4.1",src:"P",q:"The ideal speedup of a k-stage pipeline for a large number of instructions approaches:",o:["1","k/2","k","k²"],a:2,e:"S = nk/(k + n − 1) → k as n grows."},
{s:"4.2",src:"J26",q:"The purpose of a cache replacement policy is to decide:",o:["What to store in cache first","Which block to evict when the cache is full","How many cache levels to use","What to keep in RAM"],a:1,e:"Policies such as LRU, FIFO, LFU and random pick the victim block on a miss when the cache (or set) is full."},
{s:"4.2",src:"J26",q:"For the fastest data access after registers, which memory should be prioritized?",o:["Hard disk","RAM","Cache memory","Secondary storage"],a:2,e:"Hierarchy (fast → slow): registers, cache, main memory, secondary storage."},
{s:"4.2",src:"J26",q:"A USB pen drive stores data in:",o:["SRAM","DRAM","Flash memory","Cache"],a:2,e:"Flash is non-volatile EEPROM-type memory. SRAM and DRAM are volatile."},
{s:"4.2",src:"P",q:"In direct-mapped cache:",o:["A block can go to any line","Each memory block maps to exactly one cache line","Blocks map to any line within a set","No tag is needed"],a:1,e:"Direct mapping: line = block mod number of lines. Fully associative: any line. Set associative: any line in one set."},
{s:"4.2",src:"P",q:"In the write-through policy:",o:["Only the cache is updated","Cache and main memory are updated together","Main memory is updated on eviction only","Writes bypass the cache"],a:1,e:"Write-through keeps memory consistent at the cost of traffic; write-back updates memory only when a dirty block is replaced."},
{s:"4.2",src:"P",q:"Hit ratio 0.9, cache time 10 ns, memory time 100 ns, simultaneous access. Average access time:",o:["10 ns","19 ns","28 ns","100 ns"],a:1,e:"0.9 × 10 + 0.1 × 100 = 9 + 10 = 19 ns. (Hierarchical access would be 10 + 0.1 × 100 = 20 ns.)"},
{s:"4.3",src:"J26",q:"In DMA, cycle stealing means:",o:["The DMA controller takes the bus for one cycle at a time to transfer a word","The CPU steals cycles from DMA","Reading protected memory","Blocking all interrupts"],a:0,e:"The DMA controller takes the bus for a cycle, moves one word and returns it, so the CPU is slowed but not stopped. Burst mode transfers a whole block at once."},
{s:"4.3",src:"J26",q:"Control of a shared system bus among several masters is maintained through:",o:["First-come first-served only","Bus arbitration (priority based)","Random selection","Memory availability"],a:1,e:"A bus arbiter grants the bus by priority (daisy chain, parallel priority, etc.)."},
{s:"4.3",src:"P",q:"In programmed I/O, the CPU:",o:["Is interrupted when the device is ready","Repeatedly checks the device status (polling)","Hands transfers to a DMA controller","Never takes part"],a:1,e:"Polling wastes CPU time; interrupt-driven I/O and DMA reduce it."},
{s:"4.3",src:"P",q:"Tightly coupled multiprocessors communicate through:",o:["Message passing over a network","Shared common memory","Email","Separate disks"],a:1,e:"Tightly coupled = shared memory; loosely coupled = distributed memory with message passing."},
{s:"4.4",src:"R",q:"A key advantage of a custom single-purpose processor is:",o:["Low NRE cost","High performance with small size and low power","Easy to change functionality","Short time to market"],a:1,e:"Custom processors are fast, small and power-efficient for one job, but have high NRE cost, long design time and little flexibility."},
{s:"4.4",src:"P",q:"NRE cost of an embedded system is:",o:["Cost per unit manufactured","One-time cost of designing the system","Running cost of power","Cost of repairs"],a:1,e:"Non-Recurring Engineering cost is paid once for design; unit cost is paid for every unit made."},
{s:"4.4",src:"P",q:"Microcontrollers and DSPs are examples of:",o:["Custom single-purpose processors","Application-specific instruction-set processors (ASIPs)","Vector displays","Bus arbiters"],a:1,e:"ASIPs are programmable processors optimized for a class of applications."},
{s:"4.5",src:"J26",q:"Emergency braking, aircraft control and patient monitoring are examples of:",o:["Soft real-time systems","Firm real-time systems","Hard real-time systems","Batch systems"],a:2,e:"Missing a deadline in a hard real-time system can be catastrophic. Multimedia streaming is soft real-time."},
{s:"4.5",src:"P",q:"A closed-loop control system differs from open-loop because it:",o:["Has no controller","Uses feedback of the output","Is always digital","Has no actuator"],a:1,e:"Closed-loop systems measure the output and correct the error; open-loop systems do not."},
{s:"4.5",src:"P",q:"A device driver is:",o:["A hardware chip","Software that lets the OS control a hardware device","A compiler","A network cable"],a:1,e:"Drivers translate generic OS requests into device-specific operations."},
{s:"4.5",src:"P",q:"Priority inversion in an RTOS is commonly solved by:",o:["Round robin","Priority inheritance","Increasing time slice","Disabling the scheduler forever"],a:1,e:"The low-priority task holding a resource temporarily inherits the higher priority of the waiting task."},
{s:"4.6",src:"R",q:"VHDL stands for:",o:["Very High Definition Language","VHSIC Hardware Description Language","Virtual Hardware Design Logic","Verified Hardware Description Language"],a:1,e:"VHSIC = Very High Speed Integrated Circuit."},
{s:"4.6",src:"R",q:"How many shift operators does VHDL have?",o:["2","4","6","8"],a:2,e:"sll, srl, sla, sra, rol, ror."},
{s:"4.6",src:"P",q:"In VHDL, the entity describes ___ and the architecture describes ___.",o:["Behaviour; interface","Interface (ports); behaviour/structure","Timing; power","Libraries; packages"],a:1,e:"Entity = ports (inputs/outputs). Architecture = how it works."},
{s:"4.6",src:"P",q:"In VHDL, signal and variable assignments use:",o:["= and ==","<= and :=",":= and <=","-> and =>"],a:1,e:"signal <= value; variable := value; (variables only inside processes)."},
// ---------- Chapter 5 ----------
{s:"5.1",src:"R",q:"Which cable connects two routers (like devices) directly with traditional Ethernet ports?",o:["Straight-through","Crossover","Rollover","Coaxial"],a:1,e:"Like devices (router–router, switch–switch, PC–PC) use a crossover cable. Unlike devices use straight-through. Rollover is for the console port."},
{s:"5.1",src:"R",q:"Segmentation of data is done at which OSI layer?",o:["Network","Transport","Data link","Session"],a:1,e:"Transport layer creates segments; network layer packets; data link frames; physical bits."},
{s:"5.1",src:"PQ",q:"A full mesh network of 10 nodes needs how many duplex links?",o:["10","45","90","100"],a:1,e:"n(n − 1)/2 = 10 × 9 / 2 = 45."},
{s:"5.1",src:"P",q:"A switch operates at which OSI layer?",o:["Physical","Data link","Network","Transport"],a:1,e:"Hub: physical. Switch and bridge: data link (MAC). Router: network (IP)."},
{s:"5.2",src:"R",q:"Which is NOT an error detection method?",o:["CRC","Checksum","Parity","Sliding window"],a:3,e:"Sliding window is a flow-control protocol."},
{s:"5.2",src:"R",q:"The maximum segment length of 10BASE5 (thick Ethernet) is:",o:["100 m","185 m","500 m","5 m"],a:2,e:"10BASE5: 500 m. 10BASE2: 185 m. 10BASE-T: 100 m."},
{s:"5.2",src:"P",q:"ARP is used to find:",o:["IP from MAC","MAC from IP","Domain name from IP","Port from IP"],a:1,e:"ARP maps a known IP address to a MAC address; RARP does the reverse."},
{s:"5.2",src:"P",q:"Classic IEEE 802.3 Ethernet uses which access method?",o:["Token passing","CSMA/CD","CSMA/CA","Polling"],a:1,e:"Wired Ethernet: CSMA/CD. Wi-Fi (802.11): CSMA/CA. 802.4 token bus, 802.5 token ring."},
{s:"5.3",src:"J26",q:"Which TCP/IP protocol handles logical addressing and routing between hosts?",o:["TCP","ICMP","IP","UDP"],a:2,e:"IP operates at the network layer, assigning logical addresses and routing packets."},
{s:"5.3",src:"J26",q:"Which is NOT supported by IPv6?",o:["Multicast","Unicast","Broadcast","Anycast"],a:2,e:"IPv6 dropped broadcast and uses multicast (e.g. all-nodes) instead."},
{s:"5.3",src:"P",q:"How many usable host addresses are in a /26 subnet?",o:["30","62","64","126"],a:1,e:"32 − 26 = 6 host bits: 2⁶ − 2 = 62."},
{s:"5.3",src:"P",q:"OSPF is a ___ routing protocol, while RIP is ___.",o:["distance-vector; link-state","link-state; distance-vector","path-vector; link-state","static; dynamic"],a:1,e:"OSPF uses link-state (Dijkstra); RIP uses distance-vector (hop count, max 15); BGP is path-vector."},
{s:"5.3",src:"P",q:"An IPv6 address is how long?",o:["32 bits","64 bits","128 bits","256 bits"],a:2,e:"IPv4 is 32 bits; IPv6 is 128 bits."},
{s:"5.4",src:"J26",q:"Which transport protocol suits real-time traffic best?",o:["TCP","UDP","FTP","SMTP"],a:1,e:"UDP is connectionless with low overhead and no retransmission delay, suited to voice, video and real-time control."},
{s:"5.4",src:"R",q:"Which protocol provides reliable, connection-oriented data transfer?",o:["UDP","IP","TCP","ICMP"],a:2,e:"TCP gives ordering, acknowledgements, retransmission, flow and congestion control."},
{s:"5.4",src:"R",q:"When too many packets are present in a subnet and performance degrades, it is called:",o:["Flooding","Jamming","Congestion","Confusion"],a:2,e:"Congestion control (e.g. TCP slow start, leaky/token bucket) handles it."},
{s:"5.4",src:"P",q:"TCP connection establishment uses:",o:["Two-way handshake","Three-way handshake (SYN, SYN-ACK, ACK)","Four-way handshake","No handshake"],a:1,e:"Release uses a four-way FIN/ACK exchange."},
{s:"5.4",src:"P",q:"A socket is identified by:",o:["MAC address only","IP address + port number","Port number only","Domain name"],a:1,e:"Socket = IP:port, e.g. 192.168.1.5:80."},
{s:"5.5",src:"R",q:"Which protocol uses two parallel connections (control and data)?",o:["FTP","TCP","UDP","HTTP"],a:0,e:"FTP: port 21 for control and port 20 for data."},
{s:"5.5",src:"R",q:"An example of a P2P application is:",o:["HTTP web server","BitTorrent","DNS","SMTP server"],a:1,e:"In P2P, peers act as both clients and servers."},
{s:"5.5",src:"R",q:"Telnet is used for:",o:["File transfer","Remote login (terminal access)","Email","Name resolution"],a:1,e:"Telnet (port 23) gives unencrypted remote terminal access; SSH (22) is the secure replacement."},
{s:"5.5",src:"P",q:"DNS normally uses port:",o:["21","25","53","80"],a:2,e:"DNS 53, SMTP 25, HTTP 80, HTTPS 443."},
{s:"5.5",src:"P",q:"Which protocol is used to SEND email between mail servers?",o:["POP3","IMAP","SMTP","SNMP"],a:2,e:"SMTP sends; POP3 and IMAP retrieve. SNMP is for network management."},
{s:"5.5",src:"P",q:"Wireshark is a:",o:["Firewall","Packet capture and protocol analyzer","Web server","Routing protocol"],a:1,e:"MRTG and PRTG monitor traffic; Wireshark captures and decodes packets; Packet Tracer simulates networks."},
{s:"5.6",src:"J26",q:"Which firewall checks individual packet headers (addresses, ports) to allow or block them?",o:["Application-level gateway","Packet-filtering firewall","Stateful inspection firewall","Circuit-level gateway"],a:1,e:"Packet filters work on network/transport headers. Stateful firewalls also track connections; application gateways inspect application data."},
{s:"5.6",src:"R",q:"What securely binds a public key to its owner?",o:["SHA hash","Digital certificate","TLS session key","Firewall rule"],a:1,e:"A certificate signed by a Certificate Authority binds identity to public key."},
{s:"5.6",src:"P",q:"RSA is a:",o:["Symmetric cipher","Public-key (asymmetric) algorithm","Hash function","Routing protocol"],a:1,e:"RSA uses a public/private key pair; its security rests on factoring large numbers."},
{s:"5.6",src:"P",q:"PGP is mainly used to secure:",o:["Web traffic","Email","Wireless LANs","Routing tables"],a:1,e:"PGP secures email; SSL/TLS secures TCP connections; IPsec secures the network layer; WEP/WPA secure wireless LANs."},
{s:"5.6",src:"P",q:"A digital signature provides:",o:["Confidentiality only","Authentication, integrity and non-repudiation","Compression","Faster routing"],a:1,e:"The sender signs with their private key; anyone verifies with the public key."},
// ---------- Chapter 6 ----------
{s:"6.1",src:"R",q:"Finite automata and regular expressions are equivalent because:",o:["Both use stacks","Both describe exactly the regular languages","Both are Turing complete","Both accept context-free languages"],a:1,e:"Kleene's theorem: a language is regular iff some FA accepts it iff some regular expression describes it."},
{s:"6.1",src:"P",q:"For every NFA there exists:",o:["No equivalent DFA","An equivalent DFA","An equivalent PDA only","A smaller DFA always"],a:1,e:"Subset construction converts an NFA to a DFA (up to 2ⁿ states)."},
{s:"6.1",src:"P",q:"The pumping lemma for regular languages is used to:",o:["Prove a language is regular","Prove a language is NOT regular","Minimize a DFA","Convert NFA to DFA"],a:1,e:"It is a necessary condition, so it can only show non-regularity (e.g. aⁿbⁿ)."},
{s:"6.1",src:"P",q:"Which language is NOT regular?",o:["All strings over {a,b}","a*b*","aⁿbⁿ for n ≥ 0","Strings ending in ab"],a:2,e:"aⁿbⁿ needs unbounded counting, which a finite automaton cannot do. It is context-free."},
{s:"6.2",src:"R",q:"Chomsky Normal Form is used for:",o:["Regular grammars","Context-free grammars","Context-sensitive grammars","Turing machines"],a:1,e:"CNF productions are A → BC or A → a; it is used in the CYK algorithm and proofs about CFGs."},
{s:"6.2",src:"R",q:"A bottom-up (shift-reduce) parser constructs:",o:["Leftmost derivation","Rightmost derivation in reverse","Leftmost derivation in reverse","No derivation"],a:1,e:"Bottom-up parsers trace a rightmost derivation backwards; top-down (LL) parsers follow a leftmost derivation."},
{s:"6.2",src:"P",q:"Context-free languages are accepted by:",o:["Finite automata","Pushdown automata","Linear bounded automata only","Mealy machines"],a:1,e:"PDA = FA + stack. Regular: FA; context-sensitive: LBA; recursively enumerable: TM."},
{s:"6.2",src:"P",q:"A grammar is ambiguous if some string has:",o:["No parse tree","More than one parse tree (or leftmost derivation)","Only terminal symbols","An ε-production"],a:1,e:"Ambiguity = multiple distinct parse trees for one string."},
{s:"6.3",src:"J26",q:"According to the Church–Turing thesis, a Turing machine can compute:",o:["Only deterministic problems","Anything that is algorithmically computable","Only polynomial-time problems","Only finite-state problems"],a:1,e:"Any effectively computable function can be computed by a TM."},
{s:"6.3",src:"P",q:"The halting problem is:",o:["Decidable","Undecidable","Regular","Solvable in polynomial time"],a:1,e:"No TM can decide for every TM and input whether it halts (Turing, 1936)."},
{s:"6.3",src:"P",q:"Compared to a single-tape TM, a multi-tape TM is:",o:["More powerful","Equally powerful (may be faster)","Less powerful","Only a finite automaton"],a:1,e:"Multi-tape, multi-track and non-deterministic TMs all recognize the same languages."},
{s:"6.4",src:"J26",q:"What coats the inside of a CRT screen?",o:["Aluminium","Phosphor","Silicon","Copper"],a:1,e:"Phosphor glows when hit by the electron beam. Persistence is how long it keeps glowing."},
{s:"6.4",src:"R",q:"Which algorithms are used to fill colour in a polygon?",o:["Flood fill","Scan-line fill","Boundary fill","All of these"],a:3,e:"All three are area-filling algorithms."},
{s:"6.4",src:"P",q:"In a raster-scan display, the picture is stored in:",o:["Display file of line commands","Frame buffer (refresh buffer)","Hard disk","Control memory"],a:1,e:"Raster: pixel intensities in a frame buffer. Vector (random-scan): a display list of line commands."},
{s:"6.4",src:"P",q:"Frame buffer size for 1024 × 768 resolution at 8 bits per pixel:",o:["96 KB","768 KB","1 MB","6 MB"],a:1,e:"1024 × 768 × 8 / 8 = 786,432 bytes = 768 KB."},
{s:"6.5",src:"J26",q:"Which transformation changes the shape of an object?",o:["Translation","Rotation","Uniform scaling","Shear"],a:3,e:"Shear slants an object. Translation and rotation are rigid; uniform scaling keeps shape."},
{s:"6.5",src:"R",q:"Scaling with sx ≠ sy produces:",o:["Uniform scaling","Non-uniform (differential) scaling","Reflection","Rotation"],a:1,e:"Equal factors keep proportions; unequal factors distort them."},
{s:"6.5",src:"P",q:"Cohen–Sutherland line clipping uses a region code of:",o:["2 bits","3 bits","4 bits","8 bits"],a:2,e:"One bit each for top, bottom, right and left of the window."},
{s:"6.5",src:"P",q:"Homogeneous coordinates are used in 2D graphics mainly so that:",o:["Colours can be stored","Translation can be expressed as matrix multiplication","Clipping is faster","Pixels are square"],a:1,e:"With 3×3 matrices all transformations, including translation, compose by multiplication."},
{s:"6.5",src:"P",q:"Rotating the point (1, 0) by 90° anticlockwise about the origin gives:",o:["(0, 1)","(0, −1)","(−1, 0)","(1, 1)"],a:0,e:"x′ = x cos θ − y sin θ = 0; y′ = x sin θ + y cos θ = 1."},
{s:"6.6",src:"J26",q:"How many principal reflection planes are there in 3D?",o:["2","3","4","6"],a:1,e:"Reflections about the XY, YZ and XZ planes."},
{s:"6.6",src:"J26",q:"Isometric drawings use which type of projection?",o:["Perspective","Parallel (orthographic axonometric)","Oblique perspective","Stereographic"],a:1,e:"Isometric is a parallel (axonometric) projection with the three axes 120° apart and equal foreshortening."},
{s:"6.6",src:"PQ",q:"Scaling the point (2, 0, 3) by factors (2, 2, 4) gives:",o:["(4, 0, 12)","(4, 2, 7)","(2, 0, 7)","(1, 0, 3)"],a:0,e:"Multiply each coordinate by its factor: (2×2, 0×2, 3×4)."},
{s:"6.6",src:"P",q:"In perspective projection:",o:["Parallel lines stay parallel","Parallel lines converge at vanishing points","Object size is independent of distance","Projectors are parallel"],a:1,e:"Perspective is realistic: distant objects look smaller and parallel lines meet at vanishing points."},
// ---------- Chapter 7 ----------
{s:"7.1",src:"J26",q:"Postfix form of (A + B) * C is:",o:["AB+C*","ABC+*","A+BC*","CAB+*"],a:0,e:"Convert inside the brackets first: AB+, then multiply by C: AB+C*."},
{s:"7.1",src:"R",q:"A circular queue of size n is full when:",o:["front == rear","rear == n − 1","(rear + 1) % n == front","front == 0"],a:2,e:"One slot is kept empty to distinguish full from empty (front == rear means empty)."},
{s:"7.1",src:"R",q:"Maximum height (counting levels, root = 1) of an AVL tree with 7 nodes:",o:["3","4","5","6"],a:1,e:"Minimum nodes for height h: N(h) = N(h−1) + N(h−2) + 1 → 1, 2, 4, 7. So 7 nodes allow height 4 levels (3 if height is counted in edges)."},
{s:"7.1",src:"P",q:"Inorder traversal of a binary search tree gives:",o:["Reverse order","Sorted (ascending) order","Level order","Random order"],a:1,e:"Inorder = left, root, right, which visits BST keys in ascending order."},
{s:"7.1",src:"PQ",q:"BST preorder: 30, 20, 10, 15, 25, 23, 39, 35, 42. The postorder is:",o:["15, 10, 23, 25, 20, 35, 42, 39, 30","10, 15, 20, 23, 25, 30, 35, 39, 42","15, 10, 25, 23, 20, 42, 35, 39, 30","30, 39, 42, 35, 20, 25, 23, 10, 15"],a:0,e:"Build the BST from the preorder (inorder is the sorted list), then read left, right, root."},
{s:"7.1",src:"P",q:"Time complexity of binary search on a sorted array:",o:["O(1)","O(log n)","O(n)","O(n log n)"],a:1,e:"Each step halves the search space."},
{s:"7.2",src:"J26",q:"Breadth-first search is implemented with a:",o:["Stack","Queue","Linked list","Tree"],a:1,e:"BFS: FIFO queue. DFS: stack (or recursion)."},
{s:"7.2",src:"R",q:"A stack is used in:",o:["BFS","DFS","Level-order traversal","Round-robin scheduling"],a:1,e:"DFS goes deep first using LIFO order."},
{s:"7.2",src:"R",q:"Which sorting method is NOT in-place?",o:["Merge sort","Insertion sort","Selection sort","Bubble sort"],a:0,e:"Standard merge sort needs O(n) extra space for merging."},
{s:"7.2",src:"P",q:"Dijkstra's shortest-path algorithm is a:",o:["Dynamic programming algorithm that handles negative edges","Greedy algorithm for non-negative edge weights","Divide-and-conquer algorithm","Backtracking algorithm"],a:1,e:"It greedily picks the closest unvisited vertex. With negative edges use Bellman–Ford."},
{s:"7.2",src:"P",q:"Worst-case time complexity of quick sort:",o:["O(n log n)","O(n²)","O(n)","O(log n)"],a:1,e:"Worst case occurs with bad pivots (e.g. already sorted input with first-element pivot). Average is O(n log n)."},
{s:"7.2",src:"P",q:"Linear probing is a collision resolution technique of type:",o:["Separate chaining","Open addressing","Rehashing into a tree","Double linking"],a:1,e:"Open addressing (linear, quadratic probing, double hashing) stores all keys in the table itself."},
{s:"7.3",src:"J26",q:"Which normal form requires every determinant to be a candidate key?",o:["1NF","2NF","BCNF","3NF"],a:2,e:"BCNF: for every non-trivial FD X → Y, X is a superkey."},
{s:"7.3",src:"J26",q:"A characteristic of BCNF is that it removes:",o:["Only repeating groups","Only partial dependencies","Only transitive dependencies","All non-trivial FDs whose determinant is not a candidate key"],a:3,e:"1NF: atomic values. 2NF: no partial dependency. 3NF: no transitive dependency. BCNF: every determinant is a key."},
{s:"7.3",src:"P",q:"A weak entity set:",o:["Has a primary key of its own","Depends on an owner (identifying) entity for identification","Has no attributes","Cannot participate in relationships"],a:1,e:"It has only a partial key (discriminator) and is drawn with a double rectangle."},
{s:"7.3",src:"P",q:"Which are DDL commands?",o:["SELECT, INSERT","CREATE, ALTER, DROP","UPDATE, DELETE","GRANT, REVOKE"],a:1,e:"DDL defines schema; DML (SELECT, INSERT, UPDATE, DELETE) manipulates data; DCL is GRANT/REVOKE."},
{s:"7.3",src:"P",q:"2NF removes:",o:["Repeating groups","Partial dependency on part of a composite key","Transitive dependency","Multivalued dependency"],a:1,e:"2NF = 1NF + every non-key attribute fully depends on the whole key."},
{s:"7.4",src:"R",q:"Atomicity of transactions is ensured by which DBMS component?",o:["Concurrency control manager","Transaction / recovery management","Query optimizer","Storage allocator"],a:1,e:"Atomicity (all or nothing) is ensured by the recovery/transaction manager using logs. Isolation is the concurrency-control manager's job."},
{s:"7.4",src:"P",q:"Which is NOT a necessary condition for deadlock?",o:["Mutual exclusion","Hold and wait","Preemption","Circular wait"],a:2,e:"The four Coffman conditions include NO preemption. Allowing preemption breaks deadlock."},
{s:"7.4",src:"P",q:"Two-phase locking (2PL) guarantees:",o:["Deadlock freedom","Conflict serializability","No rollbacks","Faster queries"],a:1,e:"2PL (growing then shrinking phase) ensures serializability but can still deadlock."},
{s:"7.4",src:"P",q:"In the wound–wait scheme, if an older transaction requests a lock held by a younger one:",o:["The older one waits","The older one wounds (aborts) the younger one","Both abort","The request is ignored"],a:1,e:"Wound–wait: older wounds younger; younger waits for older. Wait–die: older waits; younger dies."},
{s:"7.4",src:"P",q:"In log-based recovery, the write-ahead logging rule says:",o:["Write data before the log","Write the log record to stable storage before the data change","Never write logs","Write logs only at checkpoints"],a:1,e:"The log must reach stable storage first so changes can be undone or redone after a crash."},
{s:"7.5",src:"J26",q:"Which OS kernel component decides which process runs next?",o:["File manager","Memory manager","Process scheduler","Device driver"],a:2,e:"The scheduler applies algorithms like FCFS, SJF, priority and round robin."},
{s:"7.5",src:"R",q:"An OS that groups similar jobs and runs them together without user interaction is:",o:["Multiprocessing","Multitasking","Batch processing","Real-time"],a:2,e:"Batch systems collect jobs with similar needs and run them as a batch."},
{s:"7.5",src:"P",q:"The two atomic semaphore operations are:",o:["read and write","wait (P) and signal (V)","lock and fork","push and pop"],a:1,e:"wait decrements (and may block); signal increments (and may wake a process)."},
{s:"7.5",src:"P",q:"Which scheduling algorithm gives the minimum average waiting time?",o:["FCFS","SJF","Round robin","Priority"],a:1,e:"SJF is optimal for average waiting time but needs burst-time knowledge and can starve long jobs."},
{s:"7.5",src:"P",q:"A race condition occurs when:",o:["The CPU overheats","The result depends on the order in which processes access shared data","Two disks spin at once","A process waits forever"],a:1,e:"Prevented with mutual exclusion in the critical section."},
{s:"7.6",src:"J26",q:"Swapping in an OS means:",o:["Exchanging two registers","Moving a whole process between main memory and disk","Switching between threads","Copying cache to RAM"],a:1,e:"Swapping moves entire processes; paging moves fixed-size pages."},
{s:"7.6",src:"R",q:"LRU (Least Recently Used) is used in:",o:["CPU scheduling","Page replacement","Disk formatting","Deadlock detection"],a:1,e:"LRU replaces the page not used for the longest time (also used for cache replacement)."},
{s:"7.6",src:"PQ",q:"Page fault rate 0.01, page fault service 1000 ms, memory access 20 ms. Effective access time:",o:["30.8 ms","40 ms","22 ms","29.8 ms"],a:3,e:"EAT = (1 − p)·T + p·S = 0.99 × 20 + 0.01 × 1000 = 19.8 + 10 = 29.8 ms."},
{s:"7.6",src:"P",q:"Belady's anomaly (more frames causing more faults) can occur with:",o:["LRU","Optimal","FIFO","LFU"],a:2,e:"FIFO is not a stack algorithm, so adding frames can increase faults."},
{s:"7.6",src:"P",q:"Thrashing is when:",o:["The CPU runs too fast","The system spends more time paging than executing","Disk is full","Cache hit ratio is 100%"],a:1,e:"Too little memory per process causes constant page faults."},
// ---------- Chapter 8 ----------
{s:"8.1",src:"J26",q:"Which activity is common to all software process models?",o:["Iterative cycles","Requirement analysis and planning","Fixed timeline","Waterfall phases"],a:1,e:"Every model must understand requirements and plan, even if the timing differs."},
{s:"8.1",src:"J26",q:"What is common across different software engineering strategies?",o:["Code efficiency","Sequential phases","Requirement engineering","Formal documentation only"],a:2,e:"Requirement engineering appears in every methodology."},
{s:"8.1",src:"J26",q:"The first step in the software development process is:",o:["Design","Implementation","Requirement gathering","Testing"],a:2,e:"Requirements come before design, coding and testing."},
{s:"8.1",src:"P",q:"Which is a non-functional requirement?",o:["The system shall let users reset passwords","The system shall respond within 2 seconds","The system shall generate monthly reports","The system shall store customer orders"],a:1,e:"Non-functional = quality constraints (performance, security, usability). Functional = what the system does."},
{s:"8.1",src:"P",q:"In the V-model:",o:["Testing is skipped","Each development phase has a corresponding testing phase","Requirements are gathered last","Prototypes are thrown away"],a:1,e:"Left side: requirements → design → coding. Right side: unit → integration → system → acceptance testing."},
{s:"8.2",src:"R",q:"Which design activity transforms class models into data structures?",o:["Architectural design","Data design","Procedural design","Interface design"],a:1,e:"Pressman: data/class design converts analysis classes into design classes and data structures."},
{s:"8.2",src:"P",q:"Good modular design aims for:",o:["Low cohesion, high coupling","High cohesion, low coupling","High cohesion, high coupling","Low cohesion, low coupling"],a:1,e:"Each module does one thing well (cohesion) and depends little on others (coupling)."},
{s:"8.2",src:"P",q:"An architecture where clients request services from a central server is:",o:["Pipe and filter","Client–server","Peer-to-peer","Blackboard"],a:1,e:"Client–server separates service providers from service requesters."},
{s:"8.3",src:"J26",q:"Which testing is often referred to as (user) acceptance testing done by real users at their site?",o:["White-box","Grey-box","Alpha","Beta"],a:3,e:"Alpha: users test at the developer's site. Beta: real users in their own environment before release. Both are forms of acceptance testing; the recalled key chose beta."},
{s:"8.3",src:"P",q:"White-box testing is based on:",o:["Requirements only","Internal code structure","User interface only","Performance"],a:1,e:"White-box: paths, branches, statements. Black-box: inputs and outputs from the specification."},
{s:"8.3",src:"P",q:"COCOMO is a:",o:["Testing tool","Algorithmic cost estimation model","Process model","UML diagram"],a:1,e:"COCOMO estimates effort from size in KLOC: Effort = a(KLOC)ᵇ."},
{s:"8.3",src:"P",q:"How many maturity levels does CMMI define?",o:["3","4","5","6"],a:2,e:"Initial, Managed, Defined, Quantitatively Managed, Optimizing."},
{s:"8.4",src:"J26",q:"Which UML diagram is usually classed as static in exam keys?",o:["Sequence diagram","Use case diagram","Collaboration diagram","State diagram"],a:1,e:"Among these options, the use case diagram shows no time ordering. Note: UML 2 formally lists use case diagrams under behaviour diagrams; class and object diagrams are the true structural ones."},
{s:"8.4",src:"R",q:"Which diagram shows the relationship between actors and system functions?",o:["Use case diagram","Class diagram","Activity diagram","Deployment diagram"],a:0,e:"Use case diagrams show actors and the use cases they take part in."},
{s:"8.4",src:"PQ",q:"The three main phases of object-oriented development are:",o:["Analysis, design, testing","OO analysis, OO design, OO programming","Requirements, implementation, deployment","Planning, execution, maintenance"],a:1,e:"OOA → OOD → OOP."},
{s:"8.5",src:"P",q:"A collaboration (communication) diagram emphasizes:",o:["Time ordering of messages","Structural links between objects that send messages","Deployment of nodes","State changes of one object"],a:1,e:"Sequence diagrams emphasize time; collaboration diagrams emphasize object links, with numbered messages."},
{s:"8.5",src:"P",q:"The GRASP pattern that assigns a responsibility to the class holding the needed information is:",o:["Creator","Controller","Information Expert","Low Coupling"],a:2,e:"Information Expert: give the responsibility to the class with the information to fulfil it."},
{s:"8.5",src:"P",q:"A design class diagram (DCD) shows:",o:["Only actors","Classes with attributes, methods and navigability","Network nodes","Test cases"],a:1,e:"DCDs add methods, types and navigability to the conceptual (domain) model."},
{s:"8.6",src:"P",q:"When mapping design to code, method bodies are mainly derived from:",o:["Use case diagrams","Interaction (collaboration/sequence) diagrams","Deployment diagrams","Gantt charts"],a:1,e:"Class definitions come from DCDs; the message flow in interaction diagrams becomes the method code."},
{s:"8.6",src:"P",q:"Class definitions in code are created mainly from:",o:["Design class diagrams","Activity diagrams","ER diagrams","State charts"],a:0,e:"The DCD gives class names, attributes, method signatures and associations (as reference attributes)."},
// ---------- Chapter 9 ----------
{s:"9.1",src:"R",q:"PEAS stands for:",o:["Performance, Environment, Actuators, Sensors","Process, Execution, Agents, Systems","Perception, Environment, Action, State","Planning, Evaluation, Action, Search"],a:0,e:"PEAS describes the task environment of an agent."},
{s:"9.1",src:"P",q:"Chess without a clock is which environment type?",o:["Partially observable, stochastic","Fully observable, deterministic","Fully observable, stochastic","Partially observable, deterministic"],a:1,e:"The whole board is visible and moves have certain outcomes. Poker is partially observable; backgammon is stochastic."},
{s:"9.1",src:"P",q:"An agent that chooses actions to maximize expected 'happiness' (a measure of how good a state is) is:",o:["Simple reflex","Model-based","Goal-based","Utility-based"],a:3,e:"Utility-based agents compare states using a utility function, not just goal / not goal."},
{s:"9.2",src:"J26",q:"A* search is a form of:",o:["Depth-first search","Breadth-first search","Best-first search","Depth-limited search"],a:2,e:"A* expands the node with the lowest f(n) = g(n) + h(n); with an admissible h it is optimal."},
{s:"9.2",src:"PQ",q:"The key components of a search problem are:",o:["Initial state, successor function (actions), goal test, path cost","Initial state, goal path, heuristic only","Search space and solution only","Heuristic, goal state, solution"],a:0,e:"Initial state, actions/successor function, goal test, path cost."},
{s:"9.2",src:"P",q:"Alpha–beta pruning:",o:["Can change the minimax result","Gives the same result as minimax while examining fewer nodes","Only works for one-player games","Is an uninformed search"],a:1,e:"It skips branches that cannot affect the final decision."},
{s:"9.2",src:"P",q:"Hill climbing may fail because of:",o:["Too much memory","Local maxima, plateaus and ridges","Always finding the global optimum","Backtracking"],a:1,e:"It is greedy local search; simulated annealing allows downhill moves to escape local maxima."},
{s:"9.3",src:"P",q:"Bayes' rule is:",o:["P(A|B) = P(A)P(B)","P(A|B) = P(B|A)P(A)/P(B)","P(A|B) = P(A) + P(B)","P(A|B) = 1 − P(B|A)"],a:1,e:"It updates belief in A after evidence B."},
{s:"9.3",src:"P",q:"A semantic network represents knowledge as:",o:["Production rules only","Nodes (concepts) connected by labelled links (relations)","Truth tables","Neural weights"],a:1,e:"E.g. Dog —is-a→ Animal. Frames group attributes in slots."},
{s:"9.3",src:"P",q:"A tautology is a formula that is:",o:["Always false","True in every interpretation","True in at least one interpretation","Undefined"],a:1,e:"Valid = tautology; satisfiable = true in some interpretation; contradiction = never true."},
{s:"9.3",src:"P",q:"Resolution in propositional logic requires sentences in:",o:["DNF","CNF (conjunctive normal form)","Horn form only","Prefix form"],a:1,e:"Convert to CNF (a conjunction of clauses), then apply resolution by refutation."},
{s:"9.4",src:"R",q:"MYCIN had about ___ rules and used ___ chaining.",o:["50, forward","500, forward","500, backward","5000, backward"],a:2,e:"MYCIN, the medical diagnosis expert system, had roughly 500 production rules and used goal-driven backward chaining."},
{s:"9.4",src:"P",q:"The two core components of an expert system are:",o:["Compiler and linker","Knowledge base and inference engine","Sensors and actuators","Database and spreadsheet"],a:1,e:"Plus a user interface, explanation facility and knowledge acquisition module."},
{s:"9.4",src:"P",q:"The main challenge in natural language processing is:",o:["Lack of computers","Ambiguity","Too few languages","Fast typing"],a:1,e:"Words and sentences can have multiple meanings (lexical, syntactic, semantic ambiguity)."},
{s:"9.5",src:"J26",q:"A fuzzifier in a fuzzy logic system:",o:["Converts crisp inputs into fuzzy sets","Converts fuzzy output to crisp values","Stores rules","Compares rules"],a:0,e:"Fuzzification → inference → defuzzification (the defuzzifier gives the crisp output)."},
{s:"9.5",src:"J26",q:"Which is an example of unsupervised learning?",o:["Decision tree","Support vector machine","K-means clustering","Naive Bayes classifier"],a:2,e:"K-means groups unlabelled data. The others need labelled training data."},
{s:"9.5",src:"R",q:"Fuzzy logic is:",o:["Binary valued","Many valued (degrees of truth between 0 and 1)","Crisp logic","Only true or false"],a:1,e:"Membership values range over [0, 1]."},
{s:"9.5",src:"PQ",q:"Speech recognition and movie rating prediction are, respectively:",o:["Classification and regression","Regression and classification","Clustering and regression","Classification and clustering"],a:0,e:"Recognizing words means choosing a category; a rating is a continuous value."},
{s:"9.5",src:"PQ",q:"In a genetic algorithm for timetabling, fitness f(x) = 1/(1 + conflicts). It measures:",o:["Number of classes","Number of conflicts in the schedule","Total duration","Number of students"],a:1,e:"Fewer conflicts → higher fitness."},
{s:"9.5",src:"P",q:"The main genetic algorithm operators are:",o:["Push and pop","Selection, crossover and mutation","Fuzzification and defuzzification","Forward and backward chaining"],a:1,e:"Encode candidates as chromosomes, then repeatedly select, cross over and mutate."},
{s:"9.6",src:"J26",q:"Which activation function is used in a Hopfield network?",o:["ReLU","Sigmoid","Sign (bipolar threshold)","Softmax"],a:2,e:"Hopfield neurons output +1 or −1 and settle into stored patterns (associative memory)."},
{s:"9.6",src:"P",q:"A single-layer perceptron cannot learn:",o:["AND","OR","XOR","NOT"],a:2,e:"XOR is not linearly separable; a multilayer perceptron is needed."},
{s:"9.6",src:"P",q:"Backpropagation trains a network using:",o:["Genetic search","Gradient descent on the error","Random weights only","Hebbian rule only"],a:1,e:"Errors are propagated backwards and weights updated in the direction that reduces the error."},
{s:"9.6",src:"P",q:"The Hebbian learning rule is summarized as:",o:["Neurons that fire together wire together","Minimize squared error","Winner takes all","Always decrease weights"],a:0,e:"Weights grow when connected neurons are active together."},
// ---------- Chapter 10 ----------
{s:"10.1",src:"P",q:"In an isometric view, the three axes are inclined at:",o:["90° to each other","120° to each other (30° to horizontal)","45° to the horizontal","60° to each other"],a:1,e:"Isometric axes are 120° apart; receding lines are drawn at 30° to the horizontal."},
{s:"10.1",src:"P",q:"In first-angle projection, the top view is placed:",o:["Above the front view","Below the front view","To the left of the front view","Not drawn"],a:1,e:"First angle: top view below, left view on the right. Third angle: top view above."},
{s:"10.1",src:"P",q:"A scale of 1:100 is a:",o:["Full-size scale","Reducing scale","Enlarging scale","Diagonal scale"],a:1,e:"1 unit on the drawing = 100 units in reality."},
{s:"10.1",src:"P",q:"The size of an A4 sheet is:",o:["297 × 420 mm","210 × 297 mm","148 × 210 mm","420 × 594 mm"],a:1,e:"A3 is 297 × 420 mm; A5 is 148 × 210 mm."},
{s:"10.2",src:"J26",q:"Book value in depreciation means:",o:["Original price","Cost minus accumulated depreciation","Salvage value","Market value"],a:1,e:"Book value = initial cost − accumulated depreciation."},
{s:"10.2",src:"J26",q:"For a single conventional project, NPV and IRR evaluated independently will:",o:["Conflict","Give the same accept/reject decision","Make NPV always higher","Make IRR always higher"],a:1,e:"If NPV > 0 at MARR then IRR > MARR. Conflicts arise only when ranking mutually exclusive projects or with unconventional cash flows."},
{s:"10.2",src:"R",q:"A project is acceptable when:",o:["IRR < MARR","IRR ≥ MARR","IRR = 0","MARR = 0"],a:1,e:"IRR is the rate where NPV = 0; accept when it meets or beats the minimum attractive rate of return."},
{s:"10.2",src:"R",q:"Project A lasts 8 years and B lasts 6 years. The study period for comparing them by repeatability is:",o:["12 years","14 years","24 years","48 years"],a:2,e:"Use the least common multiple of lives: LCM(8, 6) = 24."},
{s:"10.2",src:"PQ",q:"Equipment costs $10,000, life 5 years, no salvage. Annual straight-line depreciation rate:",o:["9%","15%","10%","20%"],a:3,e:"Rate = 1/n = 1/5 = 20% ($2,000 per year)."},
{s:"10.2",src:"P",q:"Discounted payback period differs from simple payback because it:",o:["Ignores cash flows","Considers the time value of money","Uses only the final year","Uses IRR"],a:1,e:"Cash flows are discounted before accumulating them to recover the investment."},
{s:"10.3",src:"R",q:"Which is a limitation of a bar (Gantt) chart?",o:["It shows activity durations","It is easy to read","It does not show interdependencies between activities","It shows start dates"],a:2,e:"Bar charts cannot show logical dependencies or the critical path; CPM/PERT networks can."},
{s:"10.3",src:"P",q:"The critical path is:",o:["The shortest path","The longest path, with zero total float","The cheapest path","Any path with dummy activities"],a:1,e:"Its length is the minimum project duration; a delay on it delays the project."},
{s:"10.3",src:"P",q:"PERT estimates: optimistic 2, most likely 5, pessimistic 14 days. Expected time:",o:["5 days","6 days","7 days","7.5 days"],a:1,e:"t_e = (a + 4m + b)/6 = (2 + 20 + 14)/6 = 6 days."},
{s:"10.3",src:"P",q:"CPM vs PERT:",o:["CPM is probabilistic, PERT deterministic","CPM is deterministic (activity-oriented), PERT probabilistic (event-oriented)","Both are bar charts","Neither uses networks"],a:1,e:"PERT uses three time estimates for uncertain R&D-type projects; CPM uses one estimate and considers time–cost trade-off."},
{s:"10.4",src:"R",q:"CAR insurance in construction contracts stands for:",o:["Consultant's All Risk","Contractor's All Risk","Client's Assured Risk","Construction Asset Register"],a:1,e:"Contractor's All Risk covers damage to the works during construction."},
{s:"10.4",src:"R",q:"Private hydropower projects in Nepal are mostly developed under which model?",o:["BOT","BOOT","EPC only","Government force account"],a:1,e:"Independent power producers build, own, operate and transfer the plant to the government after the licence period."},
{s:"10.4",src:"P",q:"The correct order of risk management steps is:",o:["Response, identification, analysis, monitoring","Identification, analysis, response planning, monitoring","Monitoring, analysis, identification, response","Analysis, monitoring, response, identification"],a:1,e:"Identify → analyse (qualitative/quantitative) → plan responses (avoid, transfer, mitigate, accept) → monitor."},
{s:"10.4",src:"P",q:"Bid security submitted with a tender is also called:",o:["Performance bond","Earnest money","Retention money","Advance payment"],a:1,e:"Bid security (earnest money) is returned to unsuccessful bidders; the winner then gives a performance security."},
{s:"10.5",src:"P",q:"An engineer's paramount obligation under professional ethics is to:",o:["The employer's profit","Public safety, health and welfare","Personal reputation","The client's wishes in every case"],a:1,e:"Codes of ethics put public safety, health and welfare first."},
{s:"10.5",src:"P",q:"Which body registers engineers and regulates engineering practice in Nepal?",o:["Nepal Engineers' Association (NEA)","Nepal Engineering Council (NEC)","Ministry of Education","Public Service Commission"],a:1,e:"NEC is the statutory regulator. NEA is the professional association of engineers."},
{s:"10.5",src:"P",q:"Personal protective equipment (PPE) falls under:",o:["Engineering economics","Occupational health and safety","Contract management","Quality assurance"],a:1,e:"OHS covers hazard identification, PPE and safe work practices."},
{s:"10.6",src:"J26",q:"The Nepal Engineering Council Act was enacted in:",o:["2049 BS","2055 BS","2059 BS","2079 BS"],a:1,e:"NEC Act 2055 BS (1998/99 AD). Its first amendment was 2079 BS. (The recalled key said 1992 AD, which is wrong; the options were rewritten.)"},
{s:"10.6",src:"R",q:"The first amendment of the Nepal Engineering Council Act was in:",o:["2076 BS","2077 BS","2078 BS","2079 BS"],a:3,e:"The NEC Act 2055 was first amended in 2079 BS, which introduced the registration examination."},
{s:"10.6",src:"J26",q:"The tenure of the NEC Registrar is:",o:["2 years","3 years","4 years","5 years"],a:2,e:"Recalled answer: 4 years. Confirm this in the NEC Act before the exam."},
{s:"10.6",src:"R",q:"What type of organization is the Nepal Engineering Council?",o:["Government department","Private company","Autonomous statutory body","NGO"],a:2,e:"NEC is an autonomous body established under the NEC Act 2055."},
{s:"10.6",src:"P",q:"The Nepal Engineering Council Regulations were issued in:",o:["2055 BS","2057 BS","2063 BS","2079 BS"],a:1,e:"NEC Regulations 2057 BS (2001), with the third amendment in 2080 BS."}
];
